// The pronunciation dictionary half of Voice Studio's grapheme-to-phoneme path.
//
// The data is a PACKAGED ASSET (extension/public/voice/lexicon.txt.gz, 767 KB gzipped /
// 1.9 MB raw, 126,037 words), fetched and decompressed on demand — never imported as a
// module. That is the same call Grammit's speller makes for public/words.txt and Image to
// Text makes for public/ocr/eng.traineddata.gz: two megabytes compiled into JavaScript is
// two megabytes parsed on every load of every bundle that touches it.
//
// It is generated by `node scripts/gen-voice-lexicon.mjs` from the CMU Pronouncing
// Dictionary (BSD-2-Clause), which replaced the GPL-3.0 eSpeak-NG binary the `phonemizer`
// npm package bundles (#1092). Do not hand-edit the asset.
//
// The file is self-describing: its `# codes<TAB>...` header lists every ARPAbet phone in
// code order, so this module never needs a table that has to agree with the generator's.

/** The packaged asset. `chrome.runtime` in the extension; the plain path under `vite dev`,
 *  which serves public/ from the root. */
function lexiconUrl(): string {
  const rt = (globalThis as { chrome?: { runtime?: { getURL?: (p: string) => string } } }).chrome?.runtime;
  return rt?.getURL?.('voice/lexicon.txt.gz') ?? '/voice/lexicon.txt.gz';
}

/** A loaded lexicon: word -> ARPAbet phones. */
export interface Lexicon {
  /** The phones for `word` (already lowercased), or null when it is not in the dictionary. */
  lookup(word: string): string[] | null;
  /** How many words it holds — the number the tests and the diagnostics assert on. */
  readonly size: number;
}

/**
 * Build a lexicon from the asset's decompressed text. Pure, so lexicon.test.ts can drive
 * it with a fixture rather than the 767 KB file.
 *
 * Throws on a file with no `# codes` header: decoding entries against a guessed alphabet
 * would mispronounce every word in the dictionary while looking like it worked.
 */
export function parseLexicon(text: string): Lexicon {
  const words = new Map<string, string>();
  let alphabet: string[] | null = null;

  for (const line of text.split('\n')) {
    if (!line) continue;
    if (line.startsWith('#')) {
      const [key, value] = line.slice(1).trim().split('\t');
      if (key === 'codes' && value) alphabet = value.split(' ');
      continue;
    }
    const tab = line.indexOf('\t');
    if (tab > 0) words.set(line.slice(0, tab), line.slice(tab + 1));
  }
  if (!alphabet) throw new Error('voice lexicon: no "# codes" header — the file is not a lexicon we can decode');

  const phones = alphabet;
  return {
    size: words.size,
    lookup(word: string): string[] | null {
      const encoded = words.get(word);
      if (encoded === undefined) return null;
      const out: string[] = [];
      for (let i = 0; i < encoded.length; i += 1) {
        const phone = phones[encoded.charCodeAt(i) - 0x21];
        if (phone) out.push(phone);
      }
      return out;
    },
  };
}

/**
 * Read the asset, decompressing it ourselves ONLY if it is still compressed.
 *
 * Whether it is depends on who served it. Chrome hands out an extension's own files
 * verbatim, so in the shipped product these bytes are gzip and `DecompressionStream` is
 * what turns them into a dictionary. But a plain HTTP server — `vite dev`, which is how
 * the app runs during development — sees the `.gz` suffix, sets `Content-Encoding: gzip`
 * and lets the browser decompress it in the fetch. Gunzipping that a second time throws,
 * and the app loses its entire pronunciation dictionary in dev while working in the crx.
 *
 * So this decides from the BYTES rather than from the transport: `1f 8b` is gzip's magic
 * number, and its absence means the body is already the text we want.
 */
async function readMaybeGzipped(response: Response): Promise<string> {
  const bytes = new Uint8Array(await response.arrayBuffer());
  if (bytes.length < 2) throw new Error('voice lexicon: the response was empty');
  if (bytes[0] !== 0x1f || bytes[1] !== 0x8b) return new TextDecoder().decode(bytes);

  const stream = new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'));
  return new Response(stream).text();
}

let loading: Promise<Lexicon> | null = null;

/** Load the dictionary once (memoized). Concurrent callers share the one fetch. */
export function loadLexicon(): Promise<Lexicon> {
  loading ??= fetch(lexiconUrl())
    .then((r) => {
      if (!r.ok) throw new Error(`voice lexicon: ${r.status} ${r.statusText}`);
      return readMaybeGzipped(r);
    })
    .then(parseLexicon)
    .catch((err) => {
      // Let the next call retry — a memoized rejection would leave the app with no
      // dictionary for the rest of the session after one transient failure.
      loading = null;
      throw err;
    });
  return loading;
}
